import{_ as o,o as e,c as d,a2 as r}from"./chunks/framework.yO0biSGH.js";const g=JSON.parse('{"title":"Go 手册 Ryugi 风格重写设计方案","description":"","frontmatter":{},"headers":[],"relativePath":"ryugi/specs/2026-11-03-handbook-style-rewrite-design.md","filePath":"ryugi/specs/2026-11-03-handbook-style-rewrite-design.md","lastUpdated":1793667649000}'),a={name:"ryugi/specs/2026-11-03-handbook-style-rewrite-design.md"};function i(l,t,s,c,n,u){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="go-手册-ryugi-风格重写设计方案" tabindex="-1">Go 手册 Ryugi 风格重写设计方案 <a class="header-anchor" href="#go-手册-ryugi-风格重写设计方案" aria-label="Permalink to &quot;Go 手册 Ryugi 风格重写设计方案&quot;">​</a></h1><p>日期：2026-11-03 状态：澄清完成（全部决定已由所有者确认） 澄清过程：document artifact <code>document/rewrite-style-clarify</code>（<a href="http://localhost:27319/document/D0Q7FM2dVq26IcWWOgxVa%EF%BC%8C%E6%9C%AC%E5%9C%B0%E8%B7%AF%E5%BE%84" target="_blank" rel="noreferrer">http://localhost:27319/document/D0Q7FM2dVq26IcWWOgxVa，本地路径</a> <code>.ryugi/artifacts/document/rewrite-style-clarify/</code>，未入库）；风格对比 artboard <code>artboard/style-reference</code>（同目录）。</p><h2 id="_1-背景与问题" tabindex="-1">1. 背景与问题 <a class="header-anchor" href="#_1-背景与问题" aria-label="Permalink to &quot;1. 背景与问题&quot;">​</a></h2><p>仓库 golearn 是 Go 教程项目：读者主路径 <code>guide/handbook/</code>（27 节）+ 细节库 <code>notes/</code>（35 章，约 1.3 万行）+ <code>docs/</code> VitePress 站点。所有者对现状语言的判断（10-27 起）：&quot;写的一塌糊涂、东一斧头西一榔头、蜻蜓点水、问题没说到点子上&quot;，点名廖雪峰 js/python/java 教程与 dbwu/eddycjy 的 Go 文章为风格参照。本方案回答：重写成什么风格、什么范围、按什么流程、怎么验收。</p><h2 id="_2-目标-非目标" tabindex="-1">2. 目标 / 非目标 <a class="header-anchor" href="#_2-目标-非目标" aria-label="Permalink to &quot;2. 目标 / 非目标&quot;">​</a></h2><p><strong>目标</strong></p><ol><li>全部读者文档（handbook 优先，notes 排入批次）按定稿风格重写。</li><li>每节做到&quot;提纲挈领 + 机制到实现层&quot;：先给地图，再展开，关键机制讲到运行时/编译器行为。</li><li>面向 Java/TS/Python 背景读者，从其已有心智模型出发组织对比。</li></ol><p><strong>非目标</strong></p><ul><li>不改技术事实：重写是风格与结构工程，事实以 <code>work/text/</code> 原文为准。</li><li>不新增章节、不改章节编号（26 路线 / 27 决策表只随各节时长重算更新）。</li><li>不为风格放弃批审门禁：只有双审落盘（runId + 回执）算改完。</li></ul><h2 id="_3-定稿风格规范" tabindex="-1">3. 定稿风格规范 <a class="header-anchor" href="#_3-定稿风格规范" aria-label="Permalink to &quot;3. 定稿风格规范&quot;">​</a></h2><p><strong>节奏（廖雪峰式，B 档）</strong></p><ul><li>从会的代码出发 → 一次引入一个新东西 → 每段代码立刻跑出输出 → 小失败制造&quot;为什么&quot; → 失败后才给术语与原则。</li><li>修辞尺度（Q8 定案）：禁三类，悬念标题（&quot;先让问题撞墙&quot;式）、卖萌元素（💀/梗图/惊叹号轰炸）、故意隐瞒答案的倒计时写法。保三类，问题先行的引入（&quot;如果要换成短信呢？&quot;）、例子即跑、失败案例直讲并解释。标题用机制命名（&quot;接口调用在运行时怎么发生&quot;），不用悬念。</li></ul><p><strong>提纲挈领（Q9 定案：缺省模板，非硬性范式）</strong></p><ul><li>每节默认开头三件套：① 机制对照（本节新概念 × 读者已会概念 × 差异，≤6 行）；② 本节问题清单（读完能答什么）；③ 与前后节的依赖一句话。</li><li>速查/索引型内容（26 节、27 节）或机制一眼见底的小节可跳过对照表，审稿记录写一句跳过理由。形式服从内容，样张 C 的表格版被所有者判&quot;不适合人类阅读&quot;，对照信息优先用叙事段（样张 C2 形态：先地图后展开），表格只在数据天然成表时用。</li></ul><p><strong>机制深度（Q7 定案）</strong></p><ul><li>三档取&quot;机制层&quot;：讲到运行时/编译器实际做什么（itab 结构、vtable 槽位、方法集合判定），配源码级引注；不展开汇编/内存布局，深入需求给 notes/ 链接。</li><li>硬要求（S5，Round 1 定案）：面向 Java 背景，接口与多态一节必须详细对比 Java 与 Go 的多态实现机制（显式 implements + 单一 vtable vs 隐式方法集合 + itab），从 Java 工程师视角组织，含&quot;运行时成本同量级，差异在关系建立方式&quot;的结论。</li></ul><p><strong>引注（Q11 定案）</strong></p><ul><li>保留但降权：行尾小灰字（读者不打扰），不删，双审靠它逐条回对原文防杜撰（审稿 issue 统计中杜撰/归属错误占 15%）。<code>scripts/check-cite-pages.py</code> 机器校验全过（当前 2502 个页码标签），每批重写后必须复跑。</li></ul><p><strong>参照语料（Q10 定案）</strong></p><ul><li>廖雪峰 js/python/java 教程、dbwu/eddycjy Go 文章、<code>downloads/</code> 里已核实的 Tony Bai《Go语言第一课》讲义与 krm 周课文档（Gin/GORM/K8s/可观测性等 21+ 讲）。进 PROMPT 的风格参照列表；事实与引注仍以 <code>work/text/</code> 为准。</li></ul><h2 id="_4-范围-q1-q10-定案" tabindex="-1">4. 范围（Q1/Q10 定案） <a class="header-anchor" href="#_4-范围-q1-q10-定案" aria-label="Permalink to &quot;4. 范围（Q1/Q10 定案）&quot;">​</a></h2><ul><li>对象：仓库内所有面向读者的文档。<code>guide/handbook/</code> 27 节优先，<code>notes/</code> 35 章按章排入后续批次；<code>docs/</code> 镜像与 README 类导航页按仓库 mirror 规则同步（<code>scripts/mirror.sh</code> 或单篇 frontmatter 规则）。</li><li>不在范围：<code>work/</code>、<code>audit/</code>、构建脚本、练习代码。</li></ul><h2 id="_5-流程与批审机器-q5-q6-q10-定案" tabindex="-1">5. 流程与批审机器（Q5/Q6/Q10 定案） <a class="header-anchor" href="#_5-流程与批审机器-q5-q6-q10-定案" aria-label="Permalink to &quot;5. 流程与批审机器（Q5/Q6/Q10 定案）&quot;">​</a></h2><ol><li><strong>试产章</strong>：04-interfaces（所有者最有意见、已有 8 条已落盘条目可对照、10-28 有一份即兴重讲素材）。试产 = <strong>整章跑完</strong>（04 章拆成约 13 个连续区块批次串行推进，每批 1-8 条目），全部落盘后 PROMPT 模板才算定稿；不是单批定模板。</li><li><strong>批次粒度（builder check #1，本方案拍板）</strong>：沿用现有批审机器粒度，每批 = 一个连续区块 + 1-8 个条目（<code>batch.workflow</code> 上限、<code>apply.js</code> 唯一替换区块校验），不改机器。章节级主线靠<strong>区块规划</strong>保证：每章开工前先产一份区块规划（按三件套→地图→展开切分，写进批次任务描述），writer 在该区块内成稿，跨批连贯性由规划文档约束。同章<strong>待审条目随风格批次一并送审</strong>，重写正文必然覆盖它们，送审是防&quot;84-91% 引用但从未对过原文&quot;陷阱的唯一路径；落盘后按双审通过处置，台账进度跳变是预期效果。04 章 96 条待审 + 8 条已落盘全部按此进批。</li><li><strong>Java 侧事实依据（builder check #2，本方案拍板）</strong>：澄清文档中两张对比表（java-go-polymorphism / vtable-itab）是<strong>所有者已核准的事实底稿</strong>（其内容在澄清过程中由本人看过并认可样张 D 及配套图）。引用方式：正文叙述不挂页码标签（<code>work/text/</code> 无 Java 机制原文可对），在节末&quot;深读&quot;里注明&quot;Java 侧行为依据 JVM 公开规范与 HotSpot 公开资料，Go 侧见 TB29&quot;；<code>check-cite-pages.py</code> 不受影响（它只校验 W/TB 页码标签）。这是对&quot;事实以 work/text 为准&quot;边界的显式放宽，仅限 Java/TS/Python 类比句，Go 侧事实仍逐条回原文。</li><li><strong>notes 通道（builder check #3，本方案拍板）</strong>：notes 排期为独立阶段，开工前置两项工程（属构建脚本改造，已在范围内授权）：① <code>apply.js</code>/<code>handbook_validate.py</code> 的 <code>TARGET_RE</code> 扩展出 notes 路径规则（两处同步改，状态仓对等复刻不破坏）；② 台账补&quot;单元→notes 章节&quot;映射清点批次。notes 章多数无页码引注体系，风格批次只动承载句不新增事实主张，引注补录单列后续任务。开工时点：handbook 25 章全部落盘后。</li><li><strong>已落盘条目</strong>：重写触碰的章节，其已落盘条目并入新一轮批次重走双审（处理状态记&quot;风格重写&quot;）；before 取<strong>当前 handbook 文本</strong>（apply 哈希规则要求唯一匹配），after 为新文本。台账进度不回退，旧 runId 保留。</li><li><strong>风格回退检查（builder check #4，本方案拍板）</strong>：不改 <code>batch.workflow</code>/审稿 schema（动机器会破坏与 omp 18.11.1 的兼容链和状态仓对等复刻）。&quot;百科腔回退&quot;作为审稿<strong>提示词约定</strong>：双审任务描述里加一条&quot;节奏/口吻回退到百科腔或表格拼贴也算 fail&quot;，evidence 里写明位置；台账统计口径按 evidence 文本过滤。零机器改动，约束力靠提示词。</li><li><strong>工程章机制判据（builder check #5，本方案拍板）</strong>：10-25 章&quot;机制到位&quot;= <strong>把原文已有的机制讲透</strong>（执行过程、数据流、失败路径讲到读者能预测行为），不要求超出语料的内部实现深度；审稿打回标准 = 语料里有而正文没讲透，而不是&quot;不够深&quot;。这与语言章（样张 D 对照）判据不同，写进 PROMPT 模板的分章说明。</li><li><strong>风格资产载体（builder check #6，本方案拍板）</strong>：本设计方案 + 样张 C2/D 文本 + PROMPT 模板落在 <code>docs/ryugi/specs/2026-11-03-handbook-style-rewrite-design.md</code> 与 <code>docs/ryugi/specs/2026-11-03-style-samples.md</code>（随本方案提交入库），跨机经 git 可达；澄清 artifacts 留在 <code>.ryugi/</code> 仅作过程记录，不作为执行依据。样张文本从 artifacts 抄录成 Markdown。</li><li><strong>引注灰字实现（builder check #7，本方案拍板）</strong>：渲染层一次性改动列入本方案范围：<code>docs/.vitepress/theme/</code> 增加一个 markdown-it 小插件把 <code>〔Wxx pN〕</code> 标签包 span 上灰（仿 mermaid-plugin 的挂法），随下一批 docs 镜像同步时验证渲染。硬规则：任何批次不得把标签改写成脚注等其它语法；<code>check-cite-pages.py</code> 复跑时命中数不得低于批前值（防&quot;空转通过&quot;）。</li><li><strong>纪律不变</strong>：候选稿由 writer agent 产生、双审结论只能由审稿 agent 产生、先查再写台账、台账同步状态仓并互引 commit（CROSS-MACHINE.md）。</li></ol><h2 id="_6-验收-q1-定案" tabindex="-1">6. 验收（Q1 定案） <a class="header-anchor" href="#_6-验收-q1-定案" aria-label="Permalink to &quot;6. 验收（Q1 定案）&quot;">​</a></h2><p>每节双重标准：</p><ol><li><strong>体系可读</strong>：目录/索引能一眼看出体系；节首三件套（或合规跳过）在位；叙事连贯无表格拼贴感（对照样张 C2）。</li><li><strong>机制到位</strong>：核心机制讲到运行时/编译器行为层；04 章多态节含 Java↔Go 实现机制对比；引注可被机器校验通过。</li></ol><p>读者测试按 skill 完整性规则执行：只读新文能答出，为什么需要此机制、例子发生了什么、何时用、边界在哪。</p><h2 id="_7-风险与对策" tabindex="-1">7. 风险与对策 <a class="header-anchor" href="#_7-风险与对策" aria-label="Permalink to &quot;7. 风险与对策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>对策</th></tr></thead><tbody><tr><td>机制段落写成百科腔，丢掉节奏</td><td>样张 C2/D 作为 PROMPT 少样本；双审任务加提示词级&quot;节奏回退也算 fail&quot;（§5.6）</td></tr><tr><td>引注降权后审稿 agent 找不到</td><td>引注语法不变，只改视觉呈现（VitePress 插件）；check-cite-pages.py 命中数不得下降（§5.9）</td></tr><tr><td>notes 章节无批审先例</td><td>TARGET_RE 扩展 + 单元映射补录为前置工程；先试产 p2-lang-core 再放量（§5.4）</td></tr><tr><td>263 条已落盘条目重审拉长周期</td><td>与新批次同卷合并送审，不单开流程</td></tr><tr><td>Java 侧事实无原文可回对</td><td>澄清期两张对比表经所有者核准为事实底稿；节末注明依据，Go 侧仍逐条回原文（§5.3）</td></tr></tbody></table><h2 id="_8-澄清决定全录-theirs" tabindex="-1">8. 澄清决定全录（theirs） <a class="header-anchor" href="#_8-澄清决定全录-theirs" aria-label="Permalink to &quot;8. 澄清决定全录（theirs）&quot;">​</a></h2><ul><li>S1 对象：skill 管辖的全部教程文档（Q1 答复，Q10 扩大到 notes 与全部读者文档）。</li><li>S2 验收：体系一眼可见 + 机制到实现层（Q1 答复）。</li><li>S3 风格：B 档廖雪峰节奏；去悬念修辞；机制对照提纲挈领（Q2/Q3 答复 + Round 1 反馈）。</li><li>S4 试产章：04-interfaces（Q4 推荐生效）。</li><li>S5 硬要求：04 章含 Java vs Go 多态实现机制详细对比（Round 1 反馈原文）。</li><li>S6 已落盘条目重走双审、按篇分组推进（Q5/Q6 推荐生效）。</li><li>Q7 机制层深度（样张 D 为准）；Q8 修辞禁保三类（Round 2 定案）。</li><li>Q9 三件套为缺省模板非硬范式，可跳过需记录理由（评论&quot;看具体场景&quot;采纳）。</li><li>Q10 范围=全部读者文档 + downloads 参照语料（评论采纳）；before 取当前文本、26/27 豁免重写。</li><li>Q11（样张 D 下引注评论）引注保留降权为行尾小灰字。</li><li>样张 C 表格版判不合格，叙事版 C2 为正样（评论&quot;不适合人类阅读&quot;采纳）。</li></ul><h2 id="_9-builder-check-记录-2026-11-03" tabindex="-1">9. Builder check 记录（2026-11-03） <a class="header-anchor" href="#_9-builder-check-记录-2026-11-03" aria-label="Permalink to &quot;9. Builder check 记录（2026-11-03）&quot;">​</a></h2><p>复核 agent（ToxicCaterpillar）独立通读本方案后提出 7 个问题，全部按&quot;答案已定&quot;回填：</p><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>处置</th><th>落点</th></tr></thead><tbody><tr><td>1</td><td>批次粒度：条目级 vs 整章；待审条目是否搭车</td><td>保持条目级机器粒度；章节主线靠区块规划；待审条目随批送审</td><td>§5.1/5.2</td></tr><tr><td>2</td><td>Java 侧事实依据（work/text 无 Java 机制原文）</td><td>澄清期两张对比表经所有者核准为事实底稿；显式放宽类比句边界，Go 侧不放宽</td><td>§5.3</td></tr><tr><td>3</td><td>notes 批审通道（TARGET_RE 限 handbook、无单元映射）</td><td>前置工程两项，handbook 25 章落盘后开工</td><td>§5.4</td></tr><tr><td>4</td><td>风格回退 issue 是否动机器</td><td>不动机器；审稿提示词约定 + 台账统计口径</td><td>§5.6</td></tr><tr><td>5</td><td>工程章&quot;机制到位&quot;判据</td><td>= 讲透语料已有机制，非绝对内部深度；打回标准 = 语料有而正文没讲透</td><td>§5.7</td></tr><tr><td>6</td><td>样张与 PROMPT 模板的跨机载体</td><td>入库 <code>docs/ryugi/specs/</code>（本方案 + style-samples），artifacts 仅作过程记录</td><td>§5.8</td></tr><tr><td>7</td><td>引注灰字渲染层授权</td><td>VitePress 主题一次性插件，列入范围；标签语法禁改，机检命中数不得下降</td><td>§5.9</td></tr></tbody></table><p>复核认定的&quot;已有答案&quot;清单（未列为问题）：before 取当前文本、26/27 豁免、引注语法不变、范围不含 work/audit/构建脚本、镜像按 mirror 规则、三件套缺省模板可跳过、台账不回退旧 runId 保留、改例须保覆盖、时长由 check-handbook-refs.py 约束、主控核证免双审的 16 条随所在区块批次自然复盖。</p>',36)])])}const q=o(a,[["render",i]]);export{g as __pageData,q as default};
